class FakePriceService:
    def __init__(self, canned=None):
        self.canned = canned or {"A-1": Money(9, 99)}
        self.calls = []

    def price(self, sku):
        self.calls.append(sku)
        try:
            return self.canned[sku]
        except KeyError:
            raise UnknownSku(sku) from None
